def preparar_historial(apps, schema_editor):
    """No inventar referencias ni decisiones para propuestas previas a este contrato."""
    Propuesta = apps.get_model('registro', 'PropuestaNivel')
    propuestas = Propuesta.objects.using(schema_editor.connection.alias)
    incoherentes = propuestas.filter(
        models.Q(evidencia_suficiente=False, nivel__isnull=False)
        | models.Q(evidencia_suficiente=True, nivel__isnull=True)
        | models.Q(estado='aceptada', nivel__isnull=True)
    )
    ids = list(incoherentes.values_list('pk', flat=True)[:10])
    if ids:
        raise RuntimeError(
            f'Propuestas con nivel y evidencia incoherentes: {ids}. '
            'Revisar esos registros antes de aplicar 0003; no se modificaron sus resultados.'
        )
    # Ninguna propuesta previa tiene huella verificable. Conservar sus datos como
    # historial, retirando también solicitudes duplicadas antes del índice único.
    propuestas.filter(estado__in=['solicitada', 'lista']).update(estado='obsoleta')


